  m-second:
    provider: pa
rate_card:
  m-first: { input_utok: 100000, output_utok: 200000 }
  m-second: { input_utok: 100000, output_utok: 200000 }
pools:
  cap-fo:
    members:
      - { model: m-first, weight: 3 }
      - { model: m-second, weight: 1 }
    breaker: { base_cooldown_secs: 15, max_cooldown_secs: 120, trip: { mode: consecutive, consecutive_n: 1 } }
    failover: { timeout_secs: 120, max_hops: 3 }
export:
